static int _parse_prop_value(struct vcardparser_state *state)
{
    vcardproperty_kind prop_kind = vcardproperty_isa(state->prop);
    vcardvalue *value = NULL;

    NOTESTART();

    while (*state->p) {
        /* Handle control characters and break for NUL char */
        HANDLECTRL(state);

        switch (*state->p) {
